#include <bits/stdc++.h>
using namespace std;

class MinStack {
private:
    stack<long long> st;
    long long mini;
public:
    MinStack() : mini(-1) {}
    void push(int val) {
        if (st.empty()) { st.push(0); mini = val; }
        else { st.push((long long)val - mini); mini = min((long long)val, mini); }
    }
    void pop() {
        if (st.top() < 0) mini = mini - st.top();
        st.pop();
    }
    int top() { return st.top() < 0 ? (int)mini : (int)(mini + st.top()); }
    int getMin() { return (int)mini; }
};

