import java.util.ArrayDeque;
import java.util.Deque;

class MinStack {
    private Deque<long[]> stack = new ArrayDeque<>();  // {value, minSoFar}

    public void push(int val) {
        long minSoFar = stack.isEmpty() ? val : Math.min(val, stack.peek()[1]);
        stack.push(new long[]{val, minSoFar});
    }
    public void pop() { stack.pop(); }
    public int top() { return (int) stack.peek()[0]; }
    public int getMin() { return (int) stack.peek()[1]; }
}
